	if _, ok := a.Window(time.Unix(0, 3)); ok {
		t.Fatal("unaligned lookup should miss")
	}
}

// TestSparseWindowsDenseMemory is a structural check that windows with
// huge gaps between them still cost memory proportional to window count,
// not span: 1000 windows spread over the full int64 range must stay fast
// and correctly ordered.
func TestSparseWindows(t *testing.T) {
	r := New(time.Nanosecond)
	// Monotone timestamps with exponentially growing gaps, kept within a
	// single monotone Add stream.
	var at int64 = math.MinInt64 / 2
	for i := 0; i < 1000; i++ {
		if err := r.Add(time.Unix(0, at), float64(i)); err != nil {
			t.Fatal(err)
		}
		at = at/2 + math.MaxInt64/4
	}
	got := r.Windows()
	if len(got) != 1000 {
		t.Fatalf("want 1000 sparse windows, got %d", len(got))
	}
	for i := 1; i < len(got); i++ {
		if !got[i-1].Start.Before(got[i].Start) {
			t.Fatalf("sparse windows not ordered at %d", i)
		}
	}
}

